<?php require 'helpers.php';require_leader();$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT * FROM clubs WHERE id=? AND leader_id=?');$q->execute([$id,current_user()['id']]);$club=$q->fetch();if(!$club){http_response_code(404);exit('Club not found or access denied.');}$pageTitle='Manage club';
if($_SERVER['REQUEST_METHOD']==='POST'){$title=trim($_POST['title']??'');$description=trim($_POST['description']??'');$venue=trim($_POST['venue']??'');$date=$_POST['event_date']??'';$capacity=(int)($_POST['capacity']??0);if(!$title||!$venue||!$date||$capacity<1){flash('Complete all event fields and use a capacity above zero.','error');redirect('manage-club.php?id='.$id);}if(strtotime($date)<=time()){flash('Choose a future event date.','error');redirect('manage-club.php?id='.$id);}$q=$pdo->prepare('INSERT INTO events(club_id,title,description,venue,event_date,capacity) VALUES(?,?,?,?,?,?)');$q->execute([$id,$title,$description,$venue,$date,$capacity]);flash('Event created successfully.');redirect('manage-club.php?id='.$id);}
require 'header.php';$q=$pdo->prepare('SELECT e.*,(SELECT COUNT(*) FROM registrations r WHERE r.event_id=e.id) AS registered FROM events e WHERE e.club_id=? ORDER BY e.event_date DESC');$q->execute([$id]);$events=$q->fetchAll(); ?>
<section class="page-intro"><span class="eyebrow">MANAGE YOUR COMMUNITY</span><h1><?=e($club['name'])?></h1><p><?=e($club['description'])?></p><a class="text-link" href="club.php?id=<?=$id?>">View public club page →</a> · <a class="text-link" href="edit-club.php?id=<?=$id?>">Edit club profile →</a></section>
<div class="dashboard-grid"><form class="form-card" method="post"><h2>Create a new event</h2><?php csrf_field(); ?><label>Event title<input name="title" required></label><label>Description<textarea name="description" rows="3"></textarea></label><label>Venue<input name="venue" required></label><label>Date and time<input type="datetime-local" name="event_date" min="<?=date('Y-m-d\TH:i')?>" required></label><label>Capacity<input type="number" name="capacity" min="1" required></label><button class="btn primary full">Publish event</button></form><div><h2>Events</h2><?php if(!$events): ?><div class="empty">No events created yet.</div><?php endif; ?><?php foreach($events as $ev): ?><article class="list-card"><div><h3><?=e($ev['title'])?></h3><p><?=e($ev['venue'])?> · <?=date('M d, Y g:i A',strtotime($ev['event_date']))?></p><p><?=(int)$ev['registered']?> / <?=e($ev['capacity'])?> registered</p></div><div class="card-actions"><a class="btn primary small" href="event-attendees.php?id=<?=$ev['id']?>">View Attendees</a><a class="text-link" href="event.php?id=<?=$ev['id']?>">View →</a></div></article><?php endforeach; ?></div></div>
